import{_ as a,o,c as t,ae as n}from"./chunks/framework.sgRordCm.js";const s="/heidrun/screenshots/features/phone_access.png",f=JSON.parse('{"title":"The phone access","description":"From your iPhone or your iPad, see the coding agents, allow or refuse a blocked request, send a prompt, and read the end of the output.","frontmatter":{"description":"From your iPhone or your iPad, see the coding agents, allow or refuse a blocked request, send a prompt, and read the end of the output."},"headers":[],"relativePath":"features/phone_access.md","filePath":"features/phone_access.md"}'),i={name:"features/phone_access.md"};function r(c,e,h,d,l,u){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="the-phone-access" tabindex="-1">The phone access <a class="header-anchor" href="#the-phone-access" aria-label="Permalink to &quot;The phone access&quot;">​</a></h1><p>A coding agent can wait for an hour only for one permission, while you are away from your desk.</p><h2 id="what-heidrun-does" tabindex="-1">What Heidrun does <a class="header-anchor" href="#what-heidrun-does" aria-label="Permalink to &quot;What Heidrun does&quot;">​</a></h2><p>Heidrun serves a small web page from your Mac. From your iPhone or your iPad, you can:</p><ul><li>See the coding agents and their state, and find the ones that wait for a decision.</li><li>Allow or refuse the request of a blocked coding agent. The same guards as on your Mac apply to a dangerous command.</li><li>Send a prompt to a coding agent, or interrupt a coding agent.</li><li>Read the end of the output of a coding agent.</li></ul><h2 id="safe-by-design" tabindex="-1">Safe by design <a class="header-anchor" href="#safe-by-design" aria-label="Permalink to &quot;Safe by design&quot;">​</a></h2><ul><li>Heidrun serves the page only on the Tailscale address of your Mac. Tailscale is a virtual private network: only your own devices reach the page, never the open Internet.</li><li>Each request needs a pairing key. Each phone pairs once, with a QR code.</li><li>The QR code holds the pairing key. Do not show the QR code, and do not share it.</li><li>The button &quot;Revoke the paired devices&quot; makes every paired device scan the QR code again.</li></ul><h2 id="set-up-the-phone-access" tabindex="-1">Set up the phone access <a class="header-anchor" href="#set-up-the-phone-access" aria-label="Permalink to &quot;Set up the phone access&quot;">​</a></h2><ol><li>Install Tailscale on your Mac and on your iPhone or your iPad, and connect them with the same account.</li><li>In Heidrun, open the section &quot;Mobile access&quot; of the Settings window, and click &quot;Turn on mobile access&quot;. macOS can ask you to allow incoming connections for Heidrun: answer &quot;Allow&quot;.</li><li>Scan the QR code with the camera of the phone, then open the link in Safari.</li><li>In Safari, tap Share, then &quot;Add to Home Screen&quot;. Heidrun then opens like an application.</li></ol><p><img src="'+s+'" alt="The section &quot;Mobile access&quot; of the Settings window before the phone access is on: the switch &quot;Turn on mobile access&quot;, and the two steps to do before."></p><p><em>Even Odin leaves Valhalla sometimes. Now the einherjar can still reach him.</em></p>',11)])])}const m=a(i,[["render",r]]);export{f as __pageData,m as default};
